#!/usr/bin/env bash
# The public ops door takes NOTHING from the packet (design a3053877).
set -uo pipefail
if [ "$#" -ne 0 ]; then
    echo 'read-gate-storage: REFUSED — no arguments are accepted' >&2
    exit 78
fi
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
# shellcheck source=infra/estate/ops-credentials.sh
. "$HERE/../estate/ops-credentials.sh"
if ! ops_image_ready >&2; then
    echo 'read-gate-storage: CANNOT ANSWER — existing ops image unavailable' >&2
    exit 1
fi
# These are generated by the trusted door, never forwarded packet environment.
GATE_STORAGE_KUBECTL="$(ops_kubectl)" || exit 1
GATE_STORAGE_TALOS="$(ops_talosctl)" || exit 1
export GATE_STORAGE_KUBECTL GATE_STORAGE_TALOS
exec python3 -B "$HERE/gate-storage.py"
